        // Mocking n to not be a prototype property and to be a global function
        // This requires specific Node structure to satisfy the internal predicates

        boolean result = processProperties.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
    public void testShouldTraverse_GlobalFunctionDeclaration_WithNamedFunction() {
        // Mocking parent as NOT a Name (Named function case)
        when(mockParent.isName()).thenReturn(false);

        // Mocking n.getFirstChild().getString()
        when(mockNode.getFirstChild()).thenReturn(mockChild);
        when(mockChild.getString()).thenReturn("namedFunc");

        boolean result = processProperties.shouldTraverse(mockTraversal, mockNode, mockParent);

        assertTrue(result);
    }

    @Test
