        // Mocking isPrototypePropertyAssign(n) -> true
        // This requires n.getFirstChild().getLastChild().getString()

        when(mockNode.getFirstChild()).thenReturn(mockChild);
        when(mockChild.getLastChild()).thenReturn(mockLastChild);
